import json
R={}
def comb(lst):
    o=[];os=[]
    for l in lst:
        if l=='all': o.append('All of the above.');os.append('ඉහත සියල්ලම.')
        else:
            p=l.split('+')
            o.append(' and '.join(p)+' only.')
            os.append(' හා '.join(p)+' පමණි.')
    return o,os
def add(i,q,qs,o,os=None):
    R[i]=dict(q=q,qs=qs,o=o,**({'os':os} if os else {}))
